export const NOTICES_B2: Notice[] = [{"id": "b2n-b2-13-1", "zone": "", "region": 13, "kind": "notice", "title": "Bürgerversammlung zum neuen Jugendzentrum", "text": "Liebe Bürgerinnen und Bürger,\nder Gemeinderat lädt Sie am Donnerstag, dem 12. März, um 19 Uhr zu einer Bürgerversammlung in die Aula der Gesamtschule ein. Thema ist das geplante Jugendzentrum am Marktplatz.\nDer Bürgermeister hat angekündigt, die Verwaltung werde alle Einwände prüfen, bevor der Rat eine Entscheidung trifft. Wer eine Frage stellen möchte, kann sie auch vorab schriftlich einreichen. Kinder sind willkommen.\nDie Tagesordnung und die Pläne liegen ab Montag im Rathaus aus. Für Menschen mit Gehbehinderung steht ein Aufzug zur Verfügung.\nIhre Gemeindeverwaltung", "qs": [{"q": "Worum geht es bei der Versammlung?", "qZh": "大会讨论什么？", "options": ["um die Renovierung der Schule", "um ein geplantes Jugendzentrum", "um einen neuen Marktplatz"], "answer": "um ein geplantes Jugendzentrum"}, {"q": "Was hat der Bürgermeister angekündigt?", "qZh": "市长宣布了什么？", "options": ["Die Entscheidung ist schon gefallen.", "Die Verwaltung prüft alle Einwände vor der Entscheidung.", "Nur schriftliche Fragen werden beantwortet."], "answer": "Die Verwaltung prüft alle Einwände vor der Entscheidung."}, {"q": "Wo kann man die Pläne ab Montag sehen?", "qZh": "从周一起在哪里能看到规划图？", "options": ["im Rathaus", "auf dem Marktplatz", "in der Aula der Schule"], "answer": "im Rathaus"}]}, {"id": "b2n-b2-13-2", "zone": "", "region": 13, "kind": "notice", "title": "Aushang: Unterschriften für mehr Radwege", "text": "Mehr Sicherheit für Radfahrer – jetzt unterschreiben!\nUnsere Bürgerinitiative sammelt bis Ende April Unterschriften für eine Petition an den Stadtrat. Wir fordern einen durchgehenden Radweg an der Hauptstraße und eine Ampel vor der Grundschule.\nLaut Polizei sei die Zahl der Unfälle mit Radfahrern im letzten Jahr um ein Drittel gestiegen. Die Stadt habe das Problem zwar erkannt, aber noch keine Maßnahmen beschlossen.\nUnterschriftenlisten liegen in der Bücherei, im Bioladen und im Café Eck aus. Jede Unterschrift zählt!\nKontakt: radweg-jetzt@posteo.de", "qs": [{"q": "Was fordert die Bürgerinitiative?", "qZh": "这个公民倡议组织要求什么？", "options": ["einen Radweg an der Hauptstraße und eine Ampel vor der Schule", "eine neue Grundschule", "weniger Autos in der Innenstadt"], "answer": "einen Radweg an der Hauptstraße und eine Ampel vor der Schule"}, {"q": "Was sagt die Polizei laut Aushang?", "qZh": "根据告示，警方说了什么？", "options": ["Die Zahl der Unfälle ist gesunken.", "Die Unfälle mit Radfahrern sind um ein Drittel gestiegen.", "Die Stadt hat schon Maßnahmen beschlossen."], "answer": "Die Unfälle mit Radfahrern sind um ein Drittel gestiegen."}, {"q": "Wo kann man unterschreiben?", "qZh": "在哪里可以签名？", "options": ["in der Bücherei, im Bioladen und in einem Café", "nur im Rathaus", "nur online per E-Mail"], "answer": "in der Bücherei, im Bioladen und in einem Café"}]}, {"id": "b2n-b2-13-3", "zone": "", "region": 13, "kind": "notice", "title": "Wahlbenachrichtigung: Wichtige Hinweise", "text": "Hinweise zur Kommunalwahl am 9. Juni\nIhr Wahllokal ist die Turnhalle der Lindenschule. Es ist von 8 bis 18 Uhr geöffnet. Bitte bringen Sie diese Benachrichtigung und Ihren Personalausweis mit.\nWer am Wahltag verhindert ist, kann Briefwahl beantragen. Der Antrag muss spätestens am Freitag vor der Wahl bis 15 Uhr beim Wahlamt eingegangen sein.\nDas Wahlamt weist darauf hin, die Stimmabgabe sei geheim und dürfe von niemandem beeinflusst werden. Hilfe beim Wählen ist nur für Menschen mit Behinderung erlaubt. Fotos in der Wahlkabine sind verboten. Das vorläufige Ergebnis wird am Wahlabend auf der Internetseite der Stadt veröffentlicht.", "qs": [{"q": "Was muss man ins Wahllokal mitbringen?", "qZh": "去投票站要带什么？", "options": ["die Benachrichtigung und den Personalausweis", "einen Antrag auf Briefwahl", "nur den Reisepass"], "answer": "die Benachrichtigung und den Personalausweis"}, {"q": "Bis wann muss der Antrag auf Briefwahl da sein?", "qZh": "邮寄投票的申请最晚什么时候要送到？", "options": ["bis Montag vor der Wahl", "bis zum Wahltag, 18 Uhr", "bis Freitag vor der Wahl, 15 Uhr"], "answer": "bis Freitag vor der Wahl, 15 Uhr"}, {"q": "Wer darf beim Wählen Hilfe bekommen?", "qZh": "谁在投票时可以得到帮助？", "options": ["jeder, der darum bittet", "alle älteren Menschen", "nur Menschen mit Behinderung"], "answer": "nur Menschen mit Behinderung"}]}, {"id": "b2n-b2-13-4", "zone": "", "region": 13, "kind": "letter", "title": "E-Mail an den Abgeordneten", "text": "Sehr geehrter Herr Abgeordneter,\nich wende mich an Sie, weil die Buslinie 12 nach den Plänen des Verkehrsverbunds ab Herbst eingestellt werden soll. Für viele ältere Menschen in unserem Viertel ist sie die einzige Verbindung zum Krankenhaus.\nIn Ihrer Rede auf dem Marktplatz sagten Sie, Ihnen liege die Mobilität auf dem Land besonders am Herzen. Ich bitte Sie deshalb, das Thema im Kreistag zur Sprache zu bringen. Viele Nachbarn unterstützen mein Anliegen.\nGern stehe ich für ein Gespräch zur Verfügung.\nMit freundlichen Grüßen\nPetra Hollmann", "qs": [{"q": "Warum schreibt Frau Hollmann?", "qZh": "霍尔曼女士为什么写信？", "options": ["Die Buslinie 12 soll eingestellt werden.", "Sie möchte im Kreistag reden.", "Das Krankenhaus soll schließen."], "answer": "Die Buslinie 12 soll eingestellt werden."}, {"q": "Wen betrifft das Problem besonders?", "qZh": "这个问题特别影响到谁？", "options": ["Schüler auf dem Weg zur Schule", "Pendler in die Stadt", "ältere Menschen im Viertel"], "answer": "ältere Menschen im Viertel"}, {"q": "Worum bittet sie den Abgeordneten?", "qZh": "她请求议员做什么？", "options": ["eine neue Rede zu halten", "ihr eine Fahrkarte zu schicken", "das Thema im Kreistag anzusprechen"], "answer": "das Thema im Kreistag anzusprechen"}]}, {"id": "b2n-b2-13-5", "zone": "", "region": 13, "kind": "letter", "title": "Antwort der Stadtverwaltung", "text": "Sehr geehrte Frau Demir,\nvielen Dank für Ihr Schreiben vom 3. Februar, in dem Sie die fehlende Beleuchtung im Stadtpark kritisieren. Wir haben Ihre Beschwerde zur Kenntnis genommen und an das Grünflächenamt weitergeleitet.\nNach Auskunft des Amtes sei die Erneuerung der Laternen bereits für das Frühjahr geplant. Die Arbeiten würden voraussichtlich im April abgeschlossen. Danach sollen alle Hauptwege im Park beleuchtet sein.\nBis dahin empfehlen wir, abends den beleuchteten Weg entlang der Schillerstraße zu nutzen. Für Ihre Hinweise sind wir Ihnen dankbar.\nMit freundlichen Grüßen\nIhr Bürgerbüro", "qs": [{"q": "Was hat Frau Demir kritisiert?", "qZh": "德米尔女士批评了什么？", "options": ["den Lärm auf der Schillerstraße", "die fehlende Beleuchtung im Park", "schmutzige Wege im Park"], "answer": "die fehlende Beleuchtung im Park"}, {"q": "Was hat das Bürgerbüro mit der Beschwerde gemacht?", "qZh": "市民服务处怎么处理这封投诉？", "options": ["Es hat sie abgelehnt.", "Es hat sie an die Polizei geschickt.", "Es hat sie an das Grünflächenamt weitergegeben."], "answer": "Es hat sie an das Grünflächenamt weitergegeben."}, {"q": "Wann sollen die Arbeiten fertig sein?", "qZh": "工程什么时候完工？", "options": ["voraussichtlich im April", "erst im nächsten Winter", "noch im Februar"], "answer": "voraussichtlich im April"}]}, {"id": "b2n-b2-13-6", "zone": "", "region": 13, "kind": "letter", "title": "Einladung zur Podiumsdiskussion", "text": "Liebe Mitglieder und Freunde des Vereins,\nam 22. Mai findet in der Stadthalle eine Podiumsdiskussion zum Thema „Integration vor Ort“ statt. Eingeladen sind Vertreterinnen der Parteien, eine Sozialarbeiterin und zwei Menschen, die vor einigen Jahren als Asylbewerber nach Deutschland gekommen sind.\nDie Moderatorin hat uns versichert, jede Seite werde gleich viel Redezeit bekommen. Fragen aus dem Publikum sind ausdrücklich erwünscht.\nDer Eintritt ist frei, um eine Spende wird gebeten. Bitte meldet euch bis zum 15. Mai an, damit wir genug Stühle haben.\nHerzliche Grüße\nder Vorstand", "qs": [{"q": "Wer sitzt auf dem Podium?", "qZh": "谁坐在台上发言？", "options": ["nur Vertreter der Stadtverwaltung", "Schüler und Lehrer", "Politikerinnen, eine Sozialarbeiterin und zwei frühere Asylbewerber"], "answer": "Politikerinnen, eine Sozialarbeiterin und zwei frühere Asylbewerber"}, {"q": "Was hat die Moderatorin versprochen?", "qZh": "主持人承诺了什么？", "options": ["Die Diskussion dauert nur eine Stunde.", "Jede Seite bekommt gleich viel Redezeit.", "Das Publikum darf keine Fragen stellen."], "answer": "Jede Seite bekommt gleich viel Redezeit."}, {"q": "Warum soll man sich anmelden?", "qZh": "为什么要报名？", "options": ["damit genug Stühle da sind", "weil nur Mitglieder kommen dürfen", "weil der Eintritt sonst teuer ist"], "answer": "damit genug Stühle da sind"}]}, {"id": "b2n-b2-14-1", "zone": "", "region": 14, "kind": "notice", "title": "Neue Regeln für die Mülltrennung", "text": "Information der Hausverwaltung\nAufgrund neuer Vorgaben der Stadt gelten ab 1. Juli strengere Regeln für die Mülltrennung. Verpackungen aus Plastik und Metall sind ausschließlich in die gelbe Tonne zu werfen. Glas ist an den Containern an der Ecke Gartenstraße zu entsorgen.\nFalsch befüllte Tonnen werden von der Müllabfuhr nicht mehr geleert. Die zusätzlichen Kosten für eine Sonderleerung lassen sich dann leider nicht vermeiden und werden auf alle Mieter umgelegt.\nBei Fragen erreichen Sie uns montags bis freitags von 9 bis 12 Uhr. Ein Merkblatt hängt im Keller.", "qs": [{"q": "Warum gelten neue Regeln?", "qZh": "为什么有新规定？", "options": ["weil die gelbe Tonne kaputt ist", "wegen neuer Vorgaben der Stadt", "weil die Mieter sich beschwert haben"], "answer": "wegen neuer Vorgaben der Stadt"}, {"q": "Wohin gehört Glas?", "qZh": "玻璃应该扔到哪里？", "options": ["in die gelbe Tonne", "in die Container an der Gartenstraße", "in den Hausmüll"], "answer": "in die Container an der Gartenstraße"}, {"q": "Was passiert, wenn eine Tonne falsch befüllt ist?", "qZh": "垃圾桶分错了会怎样？", "options": ["Die Müllabfuhr leert sie trotzdem kostenlos.", "Sie wird nicht geleert und die Kosten zahlen alle Mieter.", "Nur der Hausmeister muss zahlen."], "answer": "Sie wird nicht geleert und die Kosten zahlen alle Mieter."}]}, {"id": "b2n-b2-14-2", "zone": "", "region": 14, "kind": "notice", "title": "Rückrufaktion im Supermarkt", "text": "Wichtiger Rückruf!\nInfolge einer Verunreinigung bei der Herstellung ruft die Firma Bergquell ihr Mineralwasser „Still“ in 1,5-Liter-Flaschen zurück. Betroffen sind Flaschen mit dem Mindesthaltbarkeitsdatum 12.09.\nIn einzelnen Flaschen wurden kleine Kunststoffteile gefunden. Das Wasser ist daher nicht zu trinken. Andere Sorten und Größen sind von dem Rückruf nicht betroffen. Wer bereits davon getrunken hat und Beschwerden bemerkt, sollte vorsichtshalber einen Arzt aufsuchen.\nKunden können die Flaschen in jeder Filiale zurückgeben. Der Kaufpreis wird auch ohne Kassenbon erstattet. Das Pfand bekommen Sie selbstverständlich ebenfalls zurück.\nWir bitten um Ihr Verständnis.", "qs": [{"q": "Warum wird das Wasser zurückgerufen?", "qZh": "为什么召回这种水？", "options": ["weil das Datum falsch gedruckt ist", "wegen kleiner Kunststoffteile in einzelnen Flaschen", "weil es zu teuer war"], "answer": "wegen kleiner Kunststoffteile in einzelnen Flaschen"}, {"q": "Welche Flaschen sind betroffen?", "qZh": "涉及哪些瓶子？", "options": ["nur kleine Flaschen mit Kohlensäure", "alle Sorten von Bergquell", "1,5-Liter-Flaschen „Still“ mit einem bestimmten Datum"], "answer": "1,5-Liter-Flaschen „Still“ mit einem bestimmten Datum"}, {"q": "Was braucht man, um das Geld zurückzubekommen?", "qZh": "要拿回钱需要什么？", "options": ["eine Bestätigung des Herstellers", "den Kassenbon und den Ausweis", "nur die Flasche, kein Kassenbon nötig"], "answer": "nur die Flasche, kein Kassenbon nötig"}]}, {"id": "b2n-b2-14-3", "zone": "", "region": 14, "kind": "notice", "title": "Repair-Café im Gemeindehaus", "text": "Reparieren statt wegwerfen!\nJeden ersten Samstag im Monat öffnet von 14 bis 17 Uhr das Repair-Café im Gemeindehaus. Ehrenamtliche Helferinnen und Helfer zeigen Ihnen, wie sich kaputte Toaster, Lampen, Fahrräder oder Kleidung reparieren lassen.\nDie Hilfe ist kostenlos, Ersatzteile müssen jedoch selbst bezahlt werden. Nicht reparierbar sind leider Mikrowellen und Geräte mit Akku, weil das zu gefährlich ist. Bitte bringen Sie nur Dinge mit, die Sie selbst tragen können.\nMit jedem reparierten Gerät verringern wir die Menge an Elektroschrott. Kaffee und Kuchen gibt es gegen eine kleine Spende.", "qs": [{"q": "Wann ist das Repair-Café geöffnet?", "qZh": "修理咖啡馆什么时候开？", "options": ["jeden Samstag den ganzen Tag", "am ersten Sonntag im Monat", "am ersten Samstag im Monat nachmittags"], "answer": "am ersten Samstag im Monat nachmittags"}, {"q": "Was muss man bezahlen?", "qZh": "什么要付钱？", "options": ["den Eintritt", "die Hilfe der Ehrenamtlichen", "die Ersatzteile"], "answer": "die Ersatzteile"}, {"q": "Was kann dort nicht repariert werden?", "qZh": "那里什么不能修？", "options": ["Fahrräder", "Kleidung", "Mikrowellen und Geräte mit Akku"], "answer": "Mikrowellen und Geräte mit Akku"}]}, {"id": "b2n-b2-14-4", "zone": "", "region": 14, "kind": "letter", "title": "Beschwerde über eine Rechnung", "text": "Sehr geehrte Damen und Herren,\nmit Ihrer Rechnung vom 4. Oktober verlangen Sie für den Monat September 89,90 Euro. Laut Vertrag beträgt die monatliche Grundgebühr jedoch 34,90 Euro. Die Differenz ist für mich nicht nachvollziehbar.\nIch habe weder zusätzliche Leistungen bestellt noch im Ausland telefoniert. Ich gehe deshalb von einem Fehler in Ihrer Abrechnung aus.\nBitte korrigieren Sie die Rechnung bis zum 20. Oktober und erstatten Sie mir den zu viel abgebuchten Betrag. Andernfalls werde ich mich an die Verbraucherzentrale wenden.\nMit freundlichen Grüßen\nJonas Albrecht", "qs": [{"q": "Wie hoch ist die Grundgebühr laut Vertrag?", "qZh": "按合同基本费是多少？", "options": ["34,90 Euro im Monat", "55 Euro im Monat", "89,90 Euro im Monat"], "answer": "34,90 Euro im Monat"}, {"q": "Warum glaubt Herr Albrecht an einen Fehler?", "qZh": "阿尔布雷希特先生为什么认为是出错了？", "options": ["Die Rechnung kam zu spät.", "Er hat den Vertrag schon gekündigt.", "Er hat keine Extras bestellt und nicht im Ausland telefoniert."], "answer": "Er hat keine Extras bestellt und nicht im Ausland telefoniert."}, {"q": "Was will er tun, wenn nichts passiert?", "qZh": "如果对方不处理他打算怎么做？", "options": ["sich an die Verbraucherzentrale wenden", "den Betrag einfach nicht zahlen", "sofort den Anbieter wechseln"], "answer": "sich an die Verbraucherzentrale wenden"}]}, {"id": "b2n-b2-14-5", "zone": "", "region": 14, "kind": "letter", "title": "Antwort der Bank zum Kredit", "text": "Sehr geehrte Frau Nowak,\nvielen Dank für Ihr Interesse an einem Kredit für die Renovierung Ihrer Wohnung. Nach Prüfung Ihrer Unterlagen können wir Ihnen ein Darlehen über 15.000 Euro mit einer Laufzeit von fünf Jahren anbieten.\nHinsichtlich des Zinssatzes ist zu beachten, dass das Angebot nur bis zum 30. November gültig ist. Eine vorzeitige Rückzahlung ist jederzeit ohne zusätzliche Gebühren möglich.\nFür die Unterzeichnung des Vertrags vereinbaren Sie bitte einen Termin in unserer Filiale. Bringen Sie dazu Ihren Ausweis und die letzten drei Gehaltsabrechnungen mit.\nMit freundlichen Grüßen\nIhre Sparkasse", "qs": [{"q": "Wofür braucht Frau Nowak den Kredit?", "qZh": "诺瓦克女士贷款做什么？", "options": ["für ein neues Auto", "für die Renovierung ihrer Wohnung", "für ihr Studium"], "answer": "für die Renovierung ihrer Wohnung"}, {"q": "Was gilt für eine frühere Rückzahlung?", "qZh": "提前还款有什么规定？", "options": ["Sie kostet eine hohe Gebühr.", "Sie ist jederzeit ohne Extragebühren möglich.", "Sie ist erst nach fünf Jahren möglich."], "answer": "Sie ist jederzeit ohne Extragebühren möglich."}, {"q": "Was soll sie zum Termin mitbringen?", "qZh": "她去预约时要带什么？", "options": ["ihren Ausweis und drei Gehaltsabrechnungen", "den Mietvertrag", "eine Bestätigung des Vermieters"], "answer": "ihren Ausweis und drei Gehaltsabrechnungen"}]}, {"id": "b2n-b2-14-6", "zone": "", "region": 14, "kind": "letter", "title": "Nachricht an die Nachbarschaft: Tauschbörse", "text": "Liebe Nachbarinnen und Nachbarn,\nviele von uns haben Dinge im Keller, die sie nicht mehr brauchen, die aber noch gut zu gebrauchen sind. Deshalb organisieren wir am Sonntag, dem 4. Oktober, eine Tauschbörse im Hof.\nMitbringen könnt ihr Kleidung, Bücher, Spielzeug und Küchengeräte, solange sie sauber und funktionsfähig sind. Geld spielt keine Rolle: Jeder nimmt mit, was er brauchen kann.\nWas am Ende übrig bleibt, spenden wir an das Sozialkaufhaus. Bei Regen findet die Tauschbörse im Gemeinschaftsraum statt.\nViele Grüße\nLena und Tarek aus Haus 3", "qs": [{"q": "Was ist eine Tauschbörse hier?", "qZh": "这里的交换集市是什么？", "options": ["Man repariert kaputte Geräte.", "Man verkauft alte Sachen gegen Geld.", "Man bringt Dinge mit und nimmt kostenlos andere mit."], "answer": "Man bringt Dinge mit und nimmt kostenlos andere mit."}, {"q": "Welche Bedingung gilt für die Sachen?", "qZh": "带来的东西有什么条件？", "options": ["Sie müssen sauber sein und funktionieren.", "Sie dürfen nur Kleidung sein.", "Sie müssen neu sein."], "answer": "Sie müssen sauber sein und funktionieren."}, {"q": "Was passiert mit den übrigen Sachen?", "qZh": "剩下的东西怎么处理？", "options": ["Sie werden an das Sozialkaufhaus gespendet.", "Sie werden weggeworfen.", "Sie bleiben im Keller."], "answer": "Sie werden an das Sozialkaufhaus gespendet."}]}, {"id": "b2n-b2-15-1", "zone": "", "region": 15, "kind": "notice", "title": "Hausordnung: Ruhezeiten und Treppenhaus", "text": "Hausordnung – bitte beachten!\nVon 22 bis 6 Uhr sowie am Sonntag gilt Nachtruhe. Bohren, Staubsaugen und laute Musik sind in dieser Zeit nicht erlaubt.\nDas Treppenhaus ist ein Fluchtweg. Kinderwagen, Fahrräder und Schuhregale dürfen dort nicht abgestellt werden. Bitte tragen Sie sperrige Gegenstände direkt in den Keller hinunter. Dort gibt es genug Platz für alle.\nWer abends spät nach Hause kommt, sollte die Haustür leise hinter sich schließen. Einige Mieter sollen sich schon über das Zuschlagen der Tür beschwert haben.\nVielen Dank für Ihre Rücksicht!\nDie Hausverwaltung", "qs": [{"q": "Was ist am Sonntag nicht erlaubt?", "qZh": "星期天不允许做什么？", "options": ["Besuch empfangen", "in den Keller gehen", "Bohren und Staubsaugen"], "answer": "Bohren und Staubsaugen"}, {"q": "Warum darf im Treppenhaus nichts stehen?", "qZh": "为什么楼梯间不能放东西？", "options": ["Es wird jeden Tag geputzt.", "Der Hausmeister braucht den Platz.", "Es ist ein Fluchtweg."], "answer": "Es ist ein Fluchtweg."}, {"q": "Worüber haben sich angeblich Mieter beschwert?", "qZh": "据说租户投诉了什么？", "options": ["über Fahrräder im Hof", "über laute Musik am Nachmittag", "über das Zuschlagen der Haustür"], "answer": "über das Zuschlagen der Haustür"}]}, {"id": "b2n-b2-15-2", "zone": "", "region": 15, "kind": "notice", "title": "Praxis Dr. Seidel: Urlaubsvertretung", "text": "Liebe Patientinnen und Patienten,\nunsere Praxis bleibt vom 29. Juli bis 16. August wegen Urlaub geschlossen. Die Vertretung übernimmt die Praxis Dr. Kahraman in der Bahnhofstraße 8. Sie ist montags bis freitags von 8 bis 13 Uhr für Sie da, mittwochs zusätzlich am Nachmittag.\nRezepte für Dauermedikamente können Sie bis zum 26. Juli bei uns abholen. Bitte denken Sie rechtzeitig daran, denn in der Vertretungspraxis dürfte es in dieser Zeit sehr voll sein.\nIn Notfällen am Abend oder am Wochenende wählen Sie bitte die 116 117. Bei Lebensgefahr rufen Sie sofort die 112.\nIhr Praxisteam", "qs": [{"q": "Wer vertritt die Praxis im Urlaub?", "qZh": "休假期间谁代诊？", "options": ["die Praxis Dr. Kahraman", "das Krankenhaus am Bahnhof", "niemand, man muss warten"], "answer": "die Praxis Dr. Kahraman"}, {"q": "Bis wann kann man Rezepte abholen?", "qZh": "处方最晚什么时候能取？", "options": ["bis zum 29. Juli", "bis zum 26. Juli", "bis zum 16. August"], "answer": "bis zum 26. Juli"}, {"q": "Wann soll man die 112 anrufen?", "qZh": "什么时候应该打 112？", "options": ["wenn man ein Rezept braucht", "bei Lebensgefahr", "bei jeder Erkältung am Wochenende"], "answer": "bei Lebensgefahr"}]}, {"id": "b2n-b2-15-3", "zone": "", "region": 15, "kind": "notice", "title": "Wanderweg gesperrt", "text": "Achtung, Wanderer!\nNach dem Unwetter vom letzten Wochenende ist der Weg vom Parkplatz zum Wasserfall gesperrt. Mehrere Bäume sind umgestürzt, und am Hang können sich jederzeit Steine lösen.\nBitte gehen Sie nicht über die Absperrung hinüber, auch wenn der Weg sicher aussieht. Die Umleitung führt über die Hütte am Sonnenhang und dauert etwa 40 Minuten länger. Festes Schuhwerk wird dringend empfohlen.\nDie Aufräumarbeiten müssten bis Ende des Monats abgeschlossen sein. Aktuelle Informationen finden Sie an der Infotafel am Parkplatz.\nIhre Forstverwaltung", "qs": [{"q": "Warum ist der Weg gesperrt?", "qZh": "这条路为什么封闭？", "options": ["Nach einem Unwetter liegen Bäume da und Steine können fallen.", "Es wird ein neuer Parkplatz gebaut.", "Der Wasserfall ist ausgetrocknet."], "answer": "Nach einem Unwetter liegen Bäume da und Steine können fallen."}, {"q": "Wie lange dauert die Umleitung länger?", "qZh": "绕行路线要多走多久？", "options": ["etwa vier Stunden", "etwa zehn Minuten", "etwa 40 Minuten"], "answer": "etwa 40 Minuten"}, {"q": "Wann sollen die Arbeiten wahrscheinlich fertig sein?", "qZh": "清理工作大概什么时候完成？", "options": ["erst im nächsten Jahr", "bis Ende des Monats", "schon morgen"], "answer": "bis Ende des Monats"}]}, {"id": "b2n-b2-15-4", "zone": "", "region": 15, "kind": "letter", "title": "Mängelanzeige an den Vermieter", "text": "Sehr geehrter Herr Krüger,\nseit etwa drei Wochen bildet sich im Schlafzimmer an der Außenwand Schimmel. Obwohl wir täglich mehrmals lüften, wird der Fleck immer größer. Die Feuchtigkeit muss also von außen kommen.\nEin Nachbar aus dem zweiten Stock hat mir erzählt, an seiner Wand soll es letztes Jahr dasselbe Problem gegeben haben. Ich bitte Sie daher, die Fassade und die Wand bis zum 15. März von einem Fachmann prüfen zu lassen.\nFotos des Schadens finden Sie im Anhang.\nMit freundlichen Grüßen\nMei Lin Zhou", "qs": [{"q": "Welches Problem gibt es in der Wohnung?", "qZh": "公寓里有什么问题？", "options": ["Die Heizung ist kaputt.", "Das Fenster lässt sich nicht öffnen.", "Schimmel an der Außenwand im Schlafzimmer"], "answer": "Schimmel an der Außenwand im Schlafzimmer"}, {"q": "Warum glaubt Frau Zhou, dass die Feuchtigkeit von außen kommt?", "qZh": "周女士为什么认为潮气来自外面？", "options": ["Ein Fachmann hat es festgestellt.", "Sie lüftet oft, aber der Fleck wird größer.", "Der Nachbar hat es ihr gesagt."], "answer": "Sie lüftet oft, aber der Fleck wird größer."}, {"q": "Was soll der Vermieter tun?", "qZh": "房东应该做什么？", "options": ["Fassade und Wand von einem Fachmann prüfen lassen", "neue Fenster einbauen", "die Miete senken"], "answer": "Fassade und Wand von einem Fachmann prüfen lassen"}]}, {"id": "b2n-b2-15-5", "zone": "", "region": 15, "kind": "letter", "title": "E-Mail an die Reiseversicherung", "text": "Sehr geehrte Damen und Herren,\nam 2. Mai musste ich meine Reise nach Portugal kurzfristig absagen, weil ich mir zwei Tage vorher das Bein gebrochen habe. Ein ärztliches Attest liegt dieser E-Mail bei.\nLaut Ihren Bedingungen werden die Stornokosten bei Krankheit oder Unfall vollständig übernommen. Das Reisebüro hat mir 640 Euro in Rechnung gestellt.\nBitte teilen Sie mir mit, ob Sie noch weitere Unterlagen benötigen und bis wann ich mit der Erstattung rechnen kann. Meine Versicherungsnummer lautet RV-48213.\nMit freundlichen Grüßen\nDaniel Ferreira", "qs": [{"q": "Warum hat Herr Ferreira die Reise abgesagt?", "qZh": "费雷拉先生为什么取消旅行？", "options": ["Er hat sich das Bein gebrochen.", "Der Flug wurde gestrichen.", "Er hatte keine Zeit mehr."], "answer": "Er hat sich das Bein gebrochen."}, {"q": "Was liegt der E-Mail bei?", "qZh": "邮件附了什么？", "options": ["ein Foto vom Hotel", "die Flugtickets", "ein ärztliches Attest"], "answer": "ein ärztliches Attest"}, {"q": "Was möchte er von der Versicherung wissen?", "qZh": "他想向保险公司了解什么？", "options": ["wie seine Versicherungsnummer lautet", "ob weitere Unterlagen nötig sind und wann er das Geld bekommt", "wie er eine neue Reise buchen kann"], "answer": "ob weitere Unterlagen nötig sind und wann er das Geld bekommt"}]}, {"id": "b2n-b2-15-6", "zone": "", "region": 15, "kind": "letter", "title": "Nachricht an die Nachbarin", "text": "Liebe Frau Brandt,\nich bin von Freitag bis Mittwoch bei meiner Schwester in Leipzig. Könnten Sie in dieser Zeit meine Pflanzen gießen? Den Schlüssel werfe ich Ihnen am Donnerstagabend in den Briefkasten.\nDie Tomaten auf dem Balkon brauchen jeden Tag Wasser, die anderen Pflanzen nur zweimal. Falls ein Paket für mich kommt, nehmen Sie es bitte an und legen Sie es einfach in den Flur.\nWenn Sie in der Wohnung sind, dürfen Sie gern auch ein Stück vom Kuchen im Kühlschrank essen. Der Postbote müsste am Montag noch einen Brief bringen.\nVielen Dank und herzliche Grüße\nIhre Sabine Weber", "qs": [{"q": "Was soll Frau Brandt tun?", "qZh": "勃兰特太太应该做什么？", "options": ["die Pflanzen gießen und ein Paket annehmen", "den Briefkasten leeren und die Wohnung putzen", "nach Leipzig mitfahren"], "answer": "die Pflanzen gießen und ein Paket annehmen"}, {"q": "Wie oft brauchen die Tomaten Wasser?", "qZh": "西红柿多久浇一次水？", "options": ["nur am Montag", "jeden Tag", "zweimal in der Woche"], "answer": "jeden Tag"}, {"q": "Wie bekommt Frau Brandt den Schlüssel?", "qZh": "勃兰特太太怎么拿到钥匙？", "options": ["Er liegt unter der Fußmatte.", "Er liegt am Donnerstagabend in ihrem Briefkasten.", "Die Schwester bringt ihn vorbei."], "answer": "Er liegt am Donnerstagabend in ihrem Briefkasten."}]}, {"id": "b2n-b2-16-1", "zone": "", "region": 16, "kind": "notice", "title": "Programmheft: Maskentheater im Stadttheater", "text": "„Das Lächeln hinter der Maske“ – ein Abend mit Commedia dell’Arte\nDie aus Venedig stammende Theaterform lebt von festen Figuren mit ausdrucksstarken Halbmasken: dem geizigen Pantalone, dem gelehrten Dottore und dem schlauen Diener Arlecchino.\nIn der von der Regisseurin Anna Lorenz neu bearbeiteten Fassung spielen sechs Schauspielerinnen und Schauspieler insgesamt achtzehn Rollen. Ein großer Teil der Dialoge wird jeden Abend improvisiert.\nDauer: ca. 2 Stunden, eine Pause. Nach der Vorstellung am Freitag findet ein Publikumsgespräch mit dem Ensemble statt. Die im Foyer ausgestellten Masken dürfen ausdrücklich berührt werden.", "qs": [{"q": "Woher stammt die Commedia dell’Arte?", "qZh": "即兴喜剧源自哪里？", "options": ["aus Venedig", "aus Paris", "aus Wien"], "answer": "aus Venedig"}, {"q": "Was ist an dieser Inszenierung besonders?", "qZh": "这次演出有什么特别之处？", "options": ["Das Stück dauert vier Stunden ohne Pause.", "Die Schauspieler tragen keine Masken.", "Sechs Personen spielen achtzehn Rollen, vieles ist improvisiert."], "answer": "Sechs Personen spielen achtzehn Rollen, vieles ist improvisiert."}, {"q": "Was darf man im Foyer tun?", "qZh": "在门厅里可以做什么？", "options": ["die ausgestellten Masken anfassen", "Masken kaufen", "mit dem Ensemble proben"], "answer": "die ausgestellten Masken anfassen"}]}, {"id": "b2n-b2-16-2", "zone": "", "region": 16, "kind": "notice", "title": "Aushang der Universitätsbibliothek", "text": "Hinweis zur Prüfungszeit\nAufgrund der stark gestiegenen Nachfrage gelten vom 1. bis 28. Februar geänderte Öffnungszeiten: Die Bibliothek ist täglich von 7 bis 24 Uhr geöffnet, auch am Wochenende.\nDie Reservierung von Arbeitsplätzen erfolgt ausschließlich über das Online-Portal. Nicht genutzte Plätze werden nach einer Abwesenheit von mehr als 60 Minuten freigegeben.\nZur Vermeidung von Störungen bitten wir um die Einhaltung absoluter Ruhe in den Lesesälen. Gespräche sind nur in den dafür vorgesehenen Gruppenräumen im Erdgeschoss gestattet. Das Mitbringen von Speisen ist in allen Lesesälen untersagt.\nIhre Universitätsbibliothek", "qs": [{"q": "Wie lange ist die Bibliothek im Februar geöffnet?", "qZh": "图书馆二月开到几点？", "options": ["nur werktags bis 20 Uhr", "täglich bis Mitternacht", "rund um die Uhr"], "answer": "täglich bis Mitternacht"}, {"q": "Was passiert mit einem Platz, wenn man länger als eine Stunde weg ist?", "qZh": "离开超过一小时，座位会怎样？", "options": ["Man muss eine Gebühr zahlen.", "Er bleibt den ganzen Tag reserviert.", "Er wird für andere freigegeben."], "answer": "Er wird für andere freigegeben."}, {"q": "Wo darf man sich unterhalten?", "qZh": "在哪里可以交谈？", "options": ["nur vor dem Gebäude", "in den Gruppenräumen im Erdgeschoss", "in allen Lesesälen"], "answer": "in den Gruppenräumen im Erdgeschoss"}]}, {"id": "b2n-b2-16-3", "zone": "", "region": 16, "kind": "notice", "title": "Ausschreibung: Schreibwettbewerb", "text": "Junge Federn – Schreibwettbewerb der Stadtbücherei\nGesucht werden bisher unveröffentlichte Kurzgeschichten zum Thema „Masken“. Teilnehmen können alle in der Stadt wohnenden Personen zwischen 16 und 25 Jahren.\nDie eingereichten Texte dürfen höchstens drei Seiten umfassen und müssen in deutscher Sprache verfasst sein. Einsendeschluss ist der 31. Mai. Pro Person ist nur ein Beitrag erlaubt.\nEine aus Autorinnen, Lehrkräften und Bibliothekaren bestehende Jury wählt die drei besten Geschichten aus. Die Preisträger lesen ihre Texte im Herbst bei einer öffentlichen Lesung vor und erhalten Büchergutscheine im Wert von bis zu 200 Euro.", "qs": [{"q": "Wer darf mitmachen?", "qZh": "谁可以参加？", "options": ["alle Schüler in Deutschland", "nur bekannte Autoren", "Menschen aus der Stadt zwischen 16 und 25 Jahren"], "answer": "Menschen aus der Stadt zwischen 16 und 25 Jahren"}, {"q": "Welche Bedingung gilt für die Texte?", "qZh": "对作品有什么要求？", "options": ["höchstens drei Seiten, auf Deutsch, noch nicht veröffentlicht", "in jeder Sprache möglich", "mindestens zehn Seiten"], "answer": "höchstens drei Seiten, auf Deutsch, noch nicht veröffentlicht"}, {"q": "Was bekommen die Gewinner?", "qZh": "获奖者得到什么？", "options": ["einen Vertrag mit einem Verlag", "eine öffentliche Lesung und Büchergutscheine", "eine Reise nach Venedig"], "answer": "eine öffentliche Lesung und Büchergutscheine"}]}, {"id": "b2n-b2-16-4", "zone": "", "region": 16, "kind": "letter", "title": "Anmeldung zum Sprachkurs", "text": "Sehr geehrte Damen und Herren,\nhiermit möchte ich mich für den Kurs „Deutsch C1 – wissenschaftliches Schreiben“ anmelden, der ab dem 7. Oktober dienstags und donnerstags stattfindet.\nIch studiere im dritten Semester Biologie und muss im nächsten Jahr meine Bachelorarbeit auf Deutsch schreiben. Das Zertifikat B2 habe ich im Sommer bestanden; eine Kopie füge ich bei.\nKönnten Sie mir bitte mitteilen, ob es noch freie Plätze gibt und ob die Kursgebühr für Studierende ermäßigt ist? Über eine baldige Antwort würde ich mich sehr freuen.\nMit freundlichen Grüßen\nLi Wen", "qs": [{"q": "Warum möchte Li Wen den Kurs besuchen?", "qZh": "李文为什么想上这门课？", "options": ["Sie muss ihre Bachelorarbeit auf Deutsch schreiben.", "Sie hat die B2-Prüfung nicht bestanden.", "Sie möchte Lehrerin werden."], "answer": "Sie muss ihre Bachelorarbeit auf Deutsch schreiben."}, {"q": "Was legt sie dem Brief bei?", "qZh": "她信里附了什么？", "options": ["ihren Studentenausweis", "eine Kopie ihres B2-Zertifikats", "die Kursgebühr"], "answer": "eine Kopie ihres B2-Zertifikats"}, {"q": "Was fragt sie?", "qZh": "她问了什么？", "options": ["wer den Kurs unterrichtet", "ob noch Plätze frei sind und ob es eine Ermäßigung gibt", "wann der Kurs zu Ende ist"], "answer": "ob noch Plätze frei sind und ob es eine Ermäßigung gibt"}]}, {"id": "b2n-b2-16-5", "zone": "", "region": 16, "kind": "letter", "title": "Brief an die Eltern der Theater-AG", "text": "Liebe Eltern,\nnach monatelangen Proben führt die Theater-AG der Klassen 8 bis 10 am 18. Juni um 18 Uhr in der Aula das selbst geschriebene Stück „Hinter den Masken“ auf. Die Kostüme und Masken haben die Schülerinnen und Schüler im Kunstunterricht selbst hergestellt.\nFür die Generalprobe am 17. Juni bitten wir um Ihre Unterstützung: Wir suchen zwei bis drei Eltern, die beim Umbau der Bühne helfen können.\nDer Eintritt ist frei. Der Erlös aus dem Verkauf von Getränken und Kuchen kommt der Anschaffung neuer Scheinwerfer zugute.\nMit herzlichen Grüßen\nFrau Engel und Herr Yilmaz", "qs": [{"q": "Wer hat die Masken gemacht?", "qZh": "面具是谁做的？", "options": ["ein professionelles Theater", "die Schülerinnen und Schüler im Kunstunterricht", "die Eltern zu Hause"], "answer": "die Schülerinnen und Schüler im Kunstunterricht"}, {"q": "Wobei sollen Eltern helfen?", "qZh": "家长要帮什么忙？", "options": ["beim Umbau der Bühne bei der Generalprobe", "beim Schreiben des Stücks", "beim Verkauf von Eintrittskarten"], "answer": "beim Umbau der Bühne bei der Generalprobe"}, {"q": "Wofür ist das Geld aus dem Verkauf?", "qZh": "义卖的钱用来做什么？", "options": ["für neue Scheinwerfer", "für einen Ausflug der Klasse", "für neue Kostüme"], "answer": "für neue Scheinwerfer"}]}, {"id": "b2n-b2-16-6", "zone": "", "region": 16, "kind": "letter", "title": "Absage eines Vortrags", "text": "Sehr geehrte Gäste unserer Vortragsreihe,\nleider müssen wir Ihnen mitteilen, dass der für den 12. November angekündigte Vortrag von Prof. Dr. Hartmann über „Masken in der Kunst Westafrikas“ krankheitsbedingt ausfallen muss.\nEin Ersatztermin im Januar ist bereits in Planung. Bereits gekaufte Eintrittskarten behalten ihre Gültigkeit oder können an der Museumskasse zurückgegeben werden.\nAls kleine Entschädigung laden wir Sie am 12. November zu einer kostenlosen Führung durch unsere neu eröffnete Ausstellung „Gesichter der Welt“ ein. Beginn ist um 18:30 Uhr im Foyer.\nMit freundlichen Grüßen\nIhr Völkerkundemuseum", "qs": [{"q": "Warum fällt der Vortrag aus?", "qZh": "讲座为什么取消？", "options": ["Der Professor ist krank.", "Das Museum wird renoviert.", "Zu wenige Karten wurden verkauft."], "answer": "Der Professor ist krank."}, {"q": "Was kann man mit gekauften Karten machen?", "qZh": "已经买的票可以怎么处理？", "options": ["nur gegen eine Gebühr umtauschen", "nichts, sie verfallen", "behalten oder an der Kasse zurückgeben"], "answer": "behalten oder an der Kasse zurückgeben"}, {"q": "Was bietet das Museum am 12. November an?", "qZh": "博物馆 11 月 12 日提供什么？", "options": ["ein Konzert im Foyer", "eine kostenlose Führung durch eine neue Ausstellung", "einen anderen Vortrag"], "answer": "eine kostenlose Führung durch eine neue Ausstellung"}]}];
